package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Explicit original Cicero inputs/choices, capacities and unresolved-result policies; no executable input. */
final class CiceroWorkflowRequest {
    private CiceroWorkflowRequest() { }
    record Request(String version,String format,String coordinates,Path counts,Path peaks,Path cells,Path embedding,Path genome,
                   List<String> numericMetadata,boolean binarize,List<Map<String,Object>> analyses,Path out,Path rscript,Path rHome,List<Path> libraries,
                   long inputBytes,int maximumPeaks,int maximumCells,int inputEntries,int intermediateEntries,long modelEntries,int windows,int chunkEntries,int outputFiles,int connectionRows,
                   int jsonBytes,int jsonNodes,long outputBytes,long auditOperations,int timeout) {
        Map<String,Object> parameters(){return values("version",version,"matrix_format",format,"coordinate_system",coordinates,"numeric_metadata",numericMetadata,"binarize",binarize,"analyses",analyses,"maximum_intermediate_entries",intermediateEntries,"maximum_model_entries",modelEntries,"maximum_windows",windows,"transport_chunk_entries",chunkEntries,"maximum_connection_rows",connectionRows);}
        Map<String,Object> effective(){var m=new LinkedHashMap<String,Object>(parameters());m.put("schema_version",1);m.put("mode","COACCESS");m.put("count_units","raw-integer-counts");m.put("counts",counts.toString());m.put("peak_metadata",peaks.toString());m.put("cell_metadata",cells.toString());m.put("embedding",embedding.toString());m.put("genome",genome.toString());m.put("out",out.toString());m.put("rscript",rscript.toString());m.put("r_home",rHome.toString());m.put("r_libraries",libraries.stream().map(Path::toString).toList());m.put("maximum_input_bytes",inputBytes);m.put("maximum_peaks",maximumPeaks);m.put("maximum_cells",maximumCells);m.put("maximum_input_entries",inputEntries);m.put("maximum_intermediate_entries",intermediateEntries);m.put("maximum_model_entries",modelEntries);m.put("maximum_json_bytes",jsonBytes);m.put("maximum_json_nodes",jsonNodes);m.put("maximum_output_bytes",outputBytes);m.put("maximum_audit_operations",auditOperations);m.put("transport_chunk_entries",chunkEntries);m.put("maximum_output_files",outputFiles);m.put("maximum_connection_rows",connectionRows);m.put("timeout_seconds",timeout);return m;}
    }
    private static Map<String,Object> values(Object... pairs){var result=new LinkedHashMap<String,Object>();for(int i=0;i<pairs.length;i+=2)result.put((String)pairs[i],pairs[i+1]);return result;}
    static Request parse(Map<String,Object> m,Path parent)throws IOException {
        allowed(m,"schema_version","mode","version","matrix_format","coordinate_system","count_units","counts","peak_metadata","cell_metadata","embedding","genome","numeric_metadata","binarize","analyses","out","rscript","r_home","r_libraries","maximum_input_bytes","maximum_peaks","maximum_cells","maximum_input_entries","maximum_intermediate_entries","maximum_model_entries","maximum_windows","transport_chunk_entries","maximum_output_files","maximum_connection_rows","maximum_json_bytes","maximum_json_nodes","maximum_output_bytes","maximum_audit_operations","timeout_seconds");
        integer(m.get("schema_version"),1,1);require(text(m.get("mode")).equals("COACCESS"),"Require mode COACCESS");String version=label(m.get("version"));require(version.matches("[0-9]+[.][0-9]+[.][0-9]+"),"Declare exact Cicero version; only1.3.9 has this runtime profile");require(text(m.get("count_units")).equals("raw-integer-counts"),"Require declared raw integer counts; no activity/TF-IDF/TPM inference");
        String format=text(m.get("matrix_format")),coordinates=text(m.get("coordinate_system"));require(Set.of("dense-tsv","matrix-market").contains(format),"Choose dense-tsv or matrix-market");require(Set.of("one-based-closed","zero-based-half-open").contains(coordinates),"Declare peak coordinates explicitly; source endpoints are never converted");
        List<String> metadata=strings(m.get("numeric_metadata"),128);require(new HashSet<>(metadata).size()==metadata.size(),"Duplicate metadata declaration");for(String c:metadata){column(c);require(!Set.of("cells","temp","Size_Factor","agg_cell","num_genes_expressed").contains(c),"Reserved original metadata column: "+c);}
        var libraries=new ArrayList<Path>();for(Object raw:list(m.get("r_libraries"))){require(libraries.size()<64,"Too many R libraries");libraries.add(resolve(parent,label(raw)));}require(!libraries.isEmpty(),"Declare exact private R libraries");
        var analyses=new ArrayList<Map<String,Object>>();var ids=new HashSet<String>();
        for(Object raw:list(m.get("analyses"))){var a=object(raw);allowed(a,"id","aggregation_seed","k","size_factor_normalize","summary_stats","model","distance_parameter","skipped_windows_policy","unresolved_connections_policy");String id=text(a.get("id"));require(id.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,63}")&&ids.add(id.toLowerCase(Locale.ROOT)),"Unique portable case-folded analysis IDs required");require(analyses.size()<32,"At most32 analyses");integer(a.get("aggregation_seed"),1,2147483646);integer(a.get("k"),2,1000000);bool(a.get("size_factor_normalize"));List<String> stats=strings(a.get("summary_stats"),128);require(new HashSet<>(stats).size()==stats.size()&&metadata.containsAll(stats),"Summary stats must name unique declared numeric metadata");
            var model=object(a.get("model"));allowed(model,"window","power","max_elements");integer(model.get("window"),2,1000000000);finite(model.get("power"),Double.MIN_NORMAL,Math.nextDown(1.0));integer(model.get("max_elements"),2,100000);
            var distance=object(a.get("distance_parameter"));String mode=text(distance.get("mode"));
            if(mode.equals("fixed")){allowed(distance,"mode","value");finite(distance.get("value"),0,1e12);}
            else {require(mode.equals("estimate"),"Distance mode must be fixed or estimate");allowed(distance,"mode","seed","maxit","sample_num","distance_constraint","convergence","max_sample_windows","require_full_sample","allow_maxit_warning");bool(distance.get("require_full_sample"));bool(distance.get("allow_maxit_warning"));integer(distance.get("seed"),1,2147483646);integer(distance.get("maxit"),1,100000);integer(distance.get("sample_num"),1,1000000);integer(distance.get("max_sample_windows"),1,1000000);require(integer(distance.get("distance_constraint"),1,1000000000)<integer(model.get("window"),2,1000000000),"Distance constraint must be smaller than source window");finite(distance.get("convergence"),Double.MIN_NORMAL,1e12);}
            require(Set.of("retain-source-dispositions","require-all-modeled").contains(text(a.get("skipped_windows_policy"))),"Declare skipped-window admission policy");require(Set.of("retain-source-NA","fail-on-NA").contains(text(a.get("unresolved_connections_policy"))),"Declare unresolved-connection policy; no NA-to-zero substitution");analyses.add(Collections.unmodifiableMap(a));
        }
        require(!analyses.isEmpty(),"Require at least one analysis");
        return new Request(version,format,coordinates,resolve(parent,label(m.get("counts"))),resolve(parent,label(m.get("peak_metadata"))),resolve(parent,label(m.get("cell_metadata"))),resolve(parent,label(m.get("embedding"))),resolve(parent,label(m.get("genome"))),List.copyOf(metadata),bool(m.get("binarize")),List.copyOf(analyses),resolve(parent,label(m.get("out"))),resolve(parent,label(m.get("rscript"))),resolve(parent,label(m.get("r_home"))),List.copyOf(libraries),
            number(m,"maximum_input_bytes",134217728,1,536870912),(int)number(m,"maximum_peaks",200000,2,1000000),(int)number(m,"maximum_cells",100000,3,1000000),(int)number(m,"maximum_input_entries",1000000,1,25000000),(int)number(m,"maximum_intermediate_entries",5000000,1,100000000),number(m,"maximum_model_entries",50000000,1,1000000000000L),(int)number(m,"maximum_windows",50000,1,1000000),(int)number(m,"transport_chunk_entries",50000,1,500000),(int)number(m,"maximum_output_files",100000,1,1000000),(int)number(m,"maximum_connection_rows",10000000,1,1000000000),(int)number(m,"maximum_json_bytes",134217728,1,536870912),(int)number(m,"maximum_json_nodes",20000000,1,200000000),number(m,"maximum_output_bytes",1073741824,1,137438953472L),number(m,"maximum_audit_operations",100000000,1,100000000000L),(int)number(m,"timeout_seconds",600,1,86400));
    }
}
